package com.codepilot1c.core.edt.development;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.math.BigDecimal;
public class DataAssertionServiceTest {
 static Map<String,Object> check(String id,String kind,Object expected){var m=new LinkedHashMap<String,Object>();m.put("id",id);m.put("query","ВЫБРАТЬ 1 КАК Значение");m.put("kind",kind);m.put("expected",expected);return m;}
 static Map<String,Object> observed(String id,Object value){var m=new LinkedHashMap<String,Object>();m.put("id",id);m.put("row_count",1);m.put("column_count",1);m.put("scalar",value);m.put("scalar_supported",true);m.put("truncated",false);return m;}
 @Test public void typedValuesDoNotCoerceStringsOrBooleans(){assertEquals(true,DataAssertionService.evaluate(List.of(check("a","scalar_equals",1)),List.of(observed("a",new BigDecimal("1.00")))).get("business_result_verified"));for(Object value:List.of("1",true))assertEquals(false,DataAssertionService.evaluate(List.of(check("a","scalar_equals",1)),List.of(observed("a",value))).get("business_result_verified"));}
 @Test public void nullRequiresExplicitCompleteScalarObservation(){assertEquals(true,DataAssertionService.evaluate(List.of(check("a","scalar_equals",null)),List.of(observed("a",null))).get("business_result_verified"));var row=observed("a",null);row.remove("scalar");assertEquals(false,DataAssertionService.evaluate(List.of(check("a","scalar_equals",null)),List.of(row)).get("business_result_verified"));}
 @Test public void truncatedAndMultiColumnResultsNeverPass(){var row=observed("a",1);row.put("truncated",true);assertEquals(false,DataAssertionService.evaluate(List.of(check("a","row_count_equals",1)),List.of(row)).get("business_result_verified"));row.put("truncated",false);row.put("column_count",2);assertEquals(false,DataAssertionService.evaluate(List.of(check("a","scalar_equals",1)),List.of(row)).get("business_result_verified"));}
 @Test public void incompleteOrMisidentifiedResultsAreRejected(){assertThrows(IllegalStateException.class,()->DataAssertionService.evaluate(List.of(check("a","scalar_equals",1)),List.of()));assertThrows(IllegalStateException.class,()->DataAssertionService.evaluate(List.of(check("a","scalar_equals",1)),List.of(observed("b",1))));}
 @Test public void invalidBatchesFailBeforeDispatch(){assertThrows(IllegalArgumentException.class,()->DataAssertionService.validate(List.of()));assertThrows(IllegalArgumentException.class,()->DataAssertionService.validate(List.of(check("a","scalar_equals",1),check("a","scalar_equals",1))));assertThrows(IllegalArgumentException.class,()->DataAssertionService.validate(List.of(check("a","row_count_equals",1.5))));}
 @Test public void claimedUnknownIsNotResubmittedAndCompletedQueryCanBeReadAfterRestart()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){
  class Backend implements DataAssertionService.Backend {int sent;boolean fail=true;public Map<String,Object> target(String p,String h,boolean r){return Map.of("project",p,"base_uuid","base");}public Map<String,Object> submit(String h,String k,List<Map<String,Object>> c){sent++;if(fail)throw new IllegalStateException("lost");return Map.of("request_id","request");}public Map<String,Object> result(String h,String r){return Map.of("state","completed","execution",Map.of("success",true,"value",List.of(observed("a",1))));}}
  var b=new Backend();var s=new DataAssertionService(f.path,b);assertThrows(IllegalStateException.class,()->s.start("P","host","one",List.of(check("a","scalar_equals",1))));b.fail=false;assertEquals("outcome_unknown",s.start("P","host","one",List.of(check("a","scalar_equals",1))).get("state"));assertEquals(1,b.sent);
  var result=s.start("P","host","two",List.of(check("a","scalar_equals",1)));assertEquals(true,new DataAssertionService(f.path,b).status((String)result.get("assertion_id")).get("business_result_verified"));assertEquals(2,b.sent);
  assertThrows(IllegalStateException.class,()->s.start("P","host","two",List.of(check("a","scalar_equals",2))));assertEquals(2,b.sent);
 }}
 @Test public void evaluatedMismatchIsKnownTerminalFailure(){var result=DataAssertionService.evaluate(List.of(check("a","scalar_equals",2)),List.of(observed("a",1)));assertEquals("failed",result.get("state"));assertEquals(true,result.get("terminal"));assertEquals(false,result.get("outcome_unknown"));assertEquals(false,result.get("business_result_verified"));}
 @Test public void knownAssertionRejectionPersistsFailureWithoutReplaying()throws Exception {try(var f=new TestDataLedgerTest.Fixture()){
  class Backend implements DataAssertionService.Backend {int sent;public Map<String,Object> target(String p,String h,boolean r){return Map.of("project",p,"base_uuid","base");}public Map<String,Object> submit(String h,String k,List<Map<String,Object>> c){sent++;return Map.of("success",false,"terminal",true,"outcome_unknown",false,"execution_state","not_dispatched","state","failed");}public Map<String,Object> result(String h,String request){throw new AssertionError("No request was submitted");}}
  var backend=new Backend();var service=new DataAssertionService(f.path,backend);var result=service.start("P","host","once",List.of(check("a","scalar_equals",1)));assertEquals("failed",result.get("state"));assertEquals(false,result.get("outcome_unknown"));assertEquals(true,result.get("terminal"));assertEquals(false,result.get("business_result_verified"));
  var restarted=new DataAssertionService(f.path,backend);assertEquals("failed",restarted.status((String)result.get("assertion_id")).get("state"));assertEquals("failed",restarted.start("P","host","once",List.of(check("a","scalar_equals",1))).get("state"));assertEquals(1,backend.sent);
 }}
}
